// friday13.cs — Friday the 13th in the proleptic Gregorian calendar
#:property PublishAot=false

var earliest = DateOnly.MinValue; // 0001-01-01
bool found = false;

// Find the earliest Friday the 13th starting from 0001-01-01
for (int year = 1; year <= 400 && !found; year++)
{
    for (int month = 1; month <= 12 && !found; month++)
    {
        var date = new DateOnly(year, month, 13);
        if (date.DayOfWeek == DayOfWeek.Friday)
        {
            Console.WriteLine($"Earliest Friday the 13th: {date:yyyy-MM-dd}");
            found = true;
        }
    }
}

// Count Friday the 13ths in a full 400-year cycle (years 1–400)
int count = 0;
for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        var date = new DateOnly(year, month, 13);
        if (date.DayOfWeek == DayOfWeek.Friday)
            count++;
    }
}

Console.WriteLine($"Friday the 13ths in a 400-year cycle: {count}");
Console.WriteLine($"Average per year: {count / 400.0:F4}");
Console.WriteLine($"Average per month: {count / 4800.0:F6}");

// Bonus: distribution by month
var byMonth = new int[12];
for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        var date = new DateOnly(year, month, 13);
        if (date.DayOfWeek == DayOfWeek.Friday)
            byMonth[month - 1]++;
    }
}

Console.WriteLine("\nDistribution by month (over 400 years):");
for (int m = 0; m < 12; m++)
{
    Console.WriteLine($"  {new DateOnly(2000, m + 1, 1):MMMM,-12} {byMonth[m]}");
}

